import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.yZB1U4Nl.js";const p=JSON.parse('{"title":"Errors","description":"","frontmatter":{},"headers":[],"relativePath":"errors.md","filePath":"errors.md"}'),c={name:"errors.md"};function a(s,e,n,i,h,l){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h1><p>Three families: host errors that become HTTP responses, kernel error codes that the host maps or passes through, and the checks <code>vlo doctor</code> prints. Source: <code>src/host/errors.ts</code>, <code>crates/kernel/src/error.rs</code>, <code>src/cli/checks.ts</code>.</p><h2 id="host-errors" tabindex="-1">Host errors <a class="header-anchor" href="#host-errors" aria-label="Permalink to &quot;Host errors&quot;">​</a></h2><p>Every class extends <code>VloError</code> (<code>code</code>, <code>status</code>, <code>message</code>) and is exported from <code>@oona/vlo/host</code>. A route catches it and answers <code>{ &quot;error&quot;: { code, message } }</code> with <code>status</code>. Anything that is not a <code>VloError</code> becomes <code>500 internal</code>.</p><table tabindex="0"><thead><tr><th>Class</th><th><code>code</code></th><th>HTTP</th><th>When</th></tr></thead><tbody><tr><td><code>RunNotFound</code></td><td><code>run_not_found</code></td><td>404</td><td>No run with that id.</td></tr><tr><td><code>TaskNotFound</code></td><td><code>task_not_found</code></td><td>404</td><td>No task with that id on a callback.</td></tr><tr><td><code>RunTerminal</code></td><td><code>run_terminal</code></td><td>409</td><td>An event other than a task result or closing marker reached a completed, failed, cancelled or continued run.</td></tr><tr><td><code>IllegalEvent</code></td><td>kernel code, see below</td><td>409</td><td>The kernel refused the event. <code>kernelError</code> holds the original <code>{ code, message, seq?, step_id? }</code>.</td></tr><tr><td><code>Nondeterminism</code></td><td><code>refold_mismatch</code></td><td>409</td><td>The checkpoint hash or a re-fold disagreed with the journal. The run is failed first with cause <code>nondeterminism_detected</code> and a <code>nondeterminism</code> marker, then this is thrown.</td></tr><tr><td><code>ReducerFailed</code></td><td><code>reducer_failed</code></td><td>409</td><td>The reducer threw (<code>WorkflowFailure</code> or anything else), or a <code>spawn</code> / <code>continue_as_new</code> named a workflow this host does not know. <code>applyEvent</code> swallows it and records the <code>fail</code> marker (cause <code>app_error</code>) with the trigger event as payload; the pre-event checkpoint stays.</td></tr><tr><td><code>WorkflowRejected</code></td><td><code>unknown_workflow</code></td><td>400</td><td>Start, fold or spawn named a workflow this host has not registered.</td></tr><tr><td><code>Unauthorized</code></td><td><code>unauthorized</code></td><td>401</td><td>Missing or wrong bearer, bad push signature, bad or expired link token.</td></tr><tr><td><code>BadRequest</code></td><td><code>bad_request</code></td><td>400</td><td>Malformed body, missing field, invalid signal payload, bad <code>max_ms</code>.</td></tr><tr><td><code>LeaseLost</code></td><td><code>lease_lost</code></td><td>410</td><td>A heartbeat for an attempt that no longer holds its lease. The worker should stop.</td></tr></tbody></table><p>Routes also raise three local ones with the same shape: <code>role_not_served</code> (404, the host lacks the role), <code>no_route</code> (404), and <code>links_disabled</code> (503, no secret to sign links with). The push endpoint answers <code>503 no_push_secret</code>, <code>404 no_handler</code> and <code>409 { &quot;duplicate&quot;: true }</code> as plain JSON.</p><h2 id="kernel-error-codes" tabindex="-1">Kernel error codes <a class="header-anchor" href="#kernel-error-codes" aria-label="Permalink to &quot;Kernel error codes&quot;">​</a></h2><p>The kernel never throws; every export returns <code>{ ok: false, error: { code, message, seq?, step_id? } }</code>. The host wraps a refusal in <code>IllegalEvent</code>, passing the code through unchanged. Three codes — <code>unknown_step</code>, <code>already_terminal</code>, <code>bad_seq</code> — are treated as &quot;already folded&quot; (an at-least-once redelivery) and answer <code>duplicate: true</code> instead of failing.</p><table tabindex="0"><thead><tr><th>Code</th><th>Raised when</th></tr></thead><tbody><tr><td><code>malformed_json</code></td><td>The input string, a payload, the reducer&#39;s state or a command&#39;s JSON does not parse.</td></tr><tr><td><code>invalid_event</code></td><td>Empty <code>run_id</code> or <code>step_id</code>; <code>random</code> is not 32 lowercase hex; both <code>payload</code> and <code>payload_ref</code> set; <code>payload_ref</code> without the <code>blob://sha256/</code> prefix; an unroutable kind/status/marker combination; a <code>payload_ref</code> reaching a fold unresolved; a lifecycle-only event sent to <code>reduce_step</code>; <code>kernel_state</code> missing on anything but <code>started</code>; event <code>run_id</code> differs from the run.</td></tr><tr><td><code>payload_too_large</code></td><td>Inline <code>payload</code> exceeds 262 144 bytes. Offload it and send <code>payload_ref</code>.</td></tr><tr><td><code>run_closed</code></td><td>The <code>RunRef</code> is already completed, failed, cancelled or continued. Distinct from the host&#39;s <code>run_terminal</code>, which refuses the event before the kernel is called.</td></tr><tr><td><code>bad_seq</code></td><td><code>started</code> arrived while <code>last_seq</code> is not 0.</td></tr><tr><td><code>unknown_step</code></td><td>No open step with that id (terminal steps are pruned, so a late duplicate lands here, as does the loser of a signal-versus-deadline race).</td></tr><tr><td><code>illegal_transition</code></td><td>Step kind does not match the event kind; the status edge is not in the step machine; an event for a higher attempt than the step&#39;s; a retry that skips attempts; <code>started</code> on a run that is not <code>created</code>; a signal for a step not <code>awaiting_signal</code>.</td></tr><tr><td><code>already_terminal</code></td><td>An event for a lower attempt than the step&#39;s, or a retry naming an attempt the step already reached.</td></tr><tr><td><code>invalid_command</code></td><td>Empty activity, workflow, signal name, emit channel or explicit step id; a timer with neither <code>fire_at_ms</code> nor <code>fire_in_ms</code>.</td></tr><tr><td><code>duplicate_step_id</code></td><td>A command&#39;s explicit <code>id</code> names a step that is still open.</td></tr><tr><td><code>multiple_completions</code></td><td>A reduction contains more than one <code>complete</code> / <code>continue_as_new</code>.</td></tr><tr><td><code>commands_after_completion</code></td><td>Any command follows a <code>complete</code> / <code>continue_as_new</code> in the same reduction.</td></tr></tbody></table><h2 id="authoring-and-runtime-errors" tabindex="-1">Authoring and runtime errors <a class="header-anchor" href="#authoring-and-runtime-errors" aria-label="Permalink to &quot;Authoring and runtime errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Package</th><th>When</th></tr></thead><tbody><tr><td><code>ActivityInputError</code></td><td><code>@oona/vlo</code></td><td><code>cmd.task(activity, input)</code> was given input that fails the activity&#39;s Zod input schema. Thrown synchronously inside the reducer, which fails the run.</td></tr><tr><td><code>WorkflowFailure</code></td><td><code>@oona/vlo</code></td><td>The deliberate way to fail a run from a reducer: <code>throw new WorkflowFailure(message, details?)</code>. <code>sequence</code> throws it for a task that did not succeed and for a <code>waitFor</code> deadline with <code>onTimeout: &quot;fail&quot;</code>.</td></tr><tr><td><code>JournalClosed</code></td><td><code>@oona/vlo/host</code></td><td>Any journal call after <code>close()</code>. <code>code: &quot;journal_closed&quot;</code>. Expected during shutdown.</td></tr><tr><td><code>LeaseLost</code></td><td><code>@oona/vlo/host</code></td><td>See above; also surfaces to a worker as a rejected <code>ctx.heartbeat()</code>, after which <code>ctx.signal</code> is aborted.</td></tr></tbody></table><h2 id="vlo-doctor" tabindex="-1"><code>vlo doctor</code> <a class="header-anchor" href="#vlo-doctor" aria-label="Permalink to &quot;`vlo doctor`&quot;">​</a></h2><p>Each check is a real round trip and prints <code>✓</code>, <code>⚠</code> or <code>✗</code> with a hint under anything that is not <code>✓</code>. Any <code>✗</code> sets exit code 1. <code>--json</code> prints the same <code>Check[]</code>.</p><table tabindex="0"><thead><tr><th>Check</th><th>Status</th><th>Hint</th><th>What to do</th></tr></thead><tbody><tr><td><code>journal</code></td><td>✗</td><td><code>journal must be a sqlite:// or postgres:// url</code></td><td>Fix <code>profile.journal</code>.</td></tr><tr><td><code>journal</code></td><td>✗</td><td><code>check the journal url and that the database is reachable</code></td><td>The empty write transaction failed after a successful migrate; check network and credentials.</td></tr><tr><td><code>journal</code></td><td>✗</td><td><code>the schema may be missing; re-run without --no-migrate</code></td><td>You skipped migrations and the tables do not exist yet.</td></tr><tr><td><code>migrate</code></td><td>⚠</td><td><code>re-run without --no-migrate to apply pending migrations</code></td><td>Informational when <code>--no-migrate</code> was passed.</td></tr><tr><td><code>migrate</code></td><td>✗</td><td><code>the journal is unreachable: check the url, host and port, and that the database is running</code></td><td>Connection refused or timed out.</td></tr><tr><td><code>migrate</code></td><td>✗</td><td><code>the journal rejected the credentials in the url</code></td><td>Wrong user or password.</td></tr><tr><td><code>migrate</code></td><td>✗</td><td><code>the database named in the url does not exist</code></td><td>Create it, or fix the URL.</td></tr><tr><td><code>migrate</code></td><td>✗</td><td><code>the journal user needs CREATE on its schema</code></td><td>Grant <code>CREATE</code> on the database so <code>CREATE SCHEMA vlo</code> can run.</td></tr><tr><td><code>blob</code></td><td>✗</td><td><code>the store is not content-addressed; payload refs would not resolve</code></td><td><code>put</code> returned something other than the sha256 of the bytes; your store breaks the contract.</td></tr><tr><td><code>blob</code></td><td>✗</td><td><code>the store is truncating writes</code></td><td><code>get</code> returned fewer bytes than were written.</td></tr><tr><td><code>blob</code></td><td>✗</td><td><code>check the blob url and that the process may write there</code></td><td>Bad URL, missing peer dependency for <code>gcs://</code>, or no write permission.</td></tr><tr><td><code>kernel</code></td><td>✗</td><td><code>run scripts/build-kernel.sh, or set VLO_KERNEL_WASM</code></td><td>The wasm is missing beside <code>src/</code> or <code>dist/</code>; build it with <code>scripts/build-kernel.sh</code> or point <code>VLO_KERNEL_WASM</code> at one.</td></tr><tr><td><code>kernel</code></td><td>⚠</td><td><code>over the 1024 KiB budget; build with --release</code></td><td>A debug build was committed.</td></tr><tr><td><code>kernel</code></td><td>✗</td><td><code>this SDK speaks protocol 1; rebuild the kernel</code></td><td>Protocol mismatch between the wasm and the SDK.</td></tr><tr><td><code>schemas</code></td><td>⚠</td><td><code>these register on the next host boot</code></td><td>No host has booted this build yet; not an error.</td></tr><tr><td><code>queue:&lt;name&gt;</code></td><td>✗</td><td><code>give the queue a url, or export defineWorker({ … }, { queues: [&quot;&lt;name&gt;&quot;] })</code></td><td>A push queue with no URL and no in-process worker can never be served.</td></tr><tr><td><code>queue:&lt;name&gt;</code></td><td>✗</td><td><code>queue url must be absolute</code></td><td>The URL did not parse.</td></tr><tr><td><code>queue:&lt;name&gt;</code></td><td>✗</td><td><code>the worker host is up but not healthy</code></td><td><code>/healthz</code> on the queue&#39;s origin answered non-2xx.</td></tr><tr><td><code>queue:&lt;name&gt;</code></td><td>✗</td><td><code>start the worker host, or fix the queue url</code></td><td><code>/healthz</code> was unreachable within 3 s.</td></tr><tr><td><code>queue:&lt;name&gt;</code></td><td>⚠</td><td><code>set \\</code>secret` on the queue; unsigned pushes are rejected by the worker`</td><td>The dispatcher refuses to push unsigned; add the shared secret.</td></tr><tr><td><code>roles</code></td><td>⚠</td><td><code>a manual dispatcher only advances on POST /v1/timers/tick; set \\</code>deploy.cron``</td><td>An orchestrator in <code>manual</code> mode with no cron declared will never move the outbox.</td></tr></tbody></table><p>Details worth knowing: <code>journal</code> reports <code>&lt;dialect&gt; · commit round trip &lt;n&gt; ms</code>; <code>kernel</code> reports <code>protocol &lt;n&gt; · &lt;size&gt; KiB</code>; <code>schemas</code> reports <code>&lt;registered&gt;/&lt;wanted&gt; registered · missing &lt;names&gt;</code>; a pull queue reports <code>pull · served by pollers</code>; with no queues configured the single check <code>queues</code> reports <code>none configured · in-process only</code>.</p>',15)])])}const m=t(c,[["render",a]]);export{p as __pageData,m as default};
